messages.content:
Tool response:
Tool: search_lots
Description: Search Lots
Parameters:
    {
      "type": "object",
      "properties": {
        "title_filter": {
          "type": "string",
          "description": "Text to search for in lot titles",
          "title": "Title Filter"
        },
        "condition": {
          "anyOf": [
            {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            {
              "type": "null"
            }
          ],
          "description": "Lot conditions to filter by (Like New, Excellent, Good, Fair, Poor)",
          "title": "Condition"
        },
        "auction_status": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Auction status to filter by (active, ended, upcoming, cancelled)",
          "title": "Auction Status"
        },
        "max_bid": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "description": "Maximum current bid amount",
          "title": "Max Bid"
        }
      },
      "required": [
        "title_filter"
      ]
    }
